130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
133	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
134	        if (currentOwner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
