223	    /**
224	     * Resolves the city name to use for a newly created owner. The supplied city is
225	     * title-cased (each whitespace-separated word starts with an upper-case letter and the
226	     * remaining letters are lower-cased), for example {@code "new york"} becomes
227	     * {@code "New York"}. However, if an owner already exists in that city (matched ignoring
228	     * letter case), the existing owner's exact spelling of the city name is reused instead, so
229	     * that all owners in a city share a single canonical spelling.
230	     *
231	     * @param city the city supplied for the owner being created, may be {@code null}
232	     * @return the city name to store and return for the owner
233	     */
234	    private String resolveCity(String city) {
235	        if (city == null) {
236	            return null;
237	        }
238	        String existingCity = this.clinicService.findAllOwners().stream()
239	            .map(Owner::getCity)
240	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
241	            .findFirst()
242	            .orElse(null);
243	        if (existingCity != null) {
244	            return existingCity;
245	        }
246	        return toTitleCase(city);
247	    }
248	
249	    /**
250	     * Title-cases the given text so that each whitespace-separated word starts with an
251	     * upper-case letter and the remaining letters are lower-cased, for example
252	     * {@code "new york"} and {@code "NEW YORK"} both become {@code "New York"}. The original
253	     * spacing between words is preserved.
254	     *
255	     * @param value the text to title-case
256	     * @return the title-cased text
257	     */
258	    private static String toTitleCase(String value) {
259	        StringBuilder result = new StringBuilder(value.length());
260	        boolean startOfWord = true;
261	        for (int i = 0; i < value.length(); i++) {
262	            char ch = value.charAt(i);
263	            if (Character.isWhitespace(ch)) {
264	                startOfWord = true;
265	                result.append(ch);
266	            } else if (startOfWord) {
267	                result.append(Character.toUpperCase(ch));
268	                startOfWord = false;
269	            } else {
270	                result.append(Character.toLowerCase(ch));
271	            }
272	        }
273	        return result.toString();
274	    }
275	
276	    /**
277	     * Builds the customer code for a newly created owner, formatted as
278	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of
279	     * owners already registered in that city, zero-padded to four digits (e.g.
280	     * {@code 'LONDON-0007'}). Cities are matched ignoring letter case so the sequence is
281	     * consistent with the upper-cased prefix.
282	     *
283	     * @param city the city of the owner being created
284	     * @return the assigned customer code
285	     */
286	    private String nextCustomerCode(String city) {
287	        long ownersInCity = this.clinicService.findAllOwners().stream()
288	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
289	            .count();
290	        return city.toUpperCase() + "-" + String.format("%04d", ownersInCity + 1);
291	    }
292	
293	    /**
294	     * Determines whether the maximum number of owners that may be registered on a single day has
295	     * already been reached. At most 20 owners may be created per day; the count is taken over the
296	     * owners whose registration date is today.
297	     *
298	     * @return {@code true} if 20 or more owners have already been registered today
299	     */
300	    private boolean isDailyRegistrationLimitReached() {
301	        LocalDate today = LocalDate.now();
302	        long ownersToday = this.clinicService.findAllOwners().stream()
303	            .filter(existing -> today.equals(existing.getRegistrationDate()))
304	            .count();
305	        return ownersToday >= 20;
306	    }
307	
308	    /**
309	     * Determines whether the city of the owner being created has already reached its capacity of
310	     * owners. At most 8 owners may be registered in a single city; the count is taken over the
311	     * existing owners whose city matches (ignoring letter case) the given city.
312	     *
313	     * @param city the city of the owner being created, may be {@code null}
314	     * @return {@code true} if the city already contains 8 or more owners
315	     */
316	    private boolean isCityCapacityReached(String city) {
317	        if (city == null) {
318	            return false;
319	        }
320	        long ownersInCity = this.clinicService.findAllOwners().stream()
321	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
322	            .count();
323	        return ownersInCity >= 8;
324	    }
325	
326	    /**
327	     * Determines whether an owner already exists that uses the same telephone number as the
328	     * given candidate. Telephone numbers are compared digits-only, so formatting characters
329	     * such as spaces, dashes and parentheses are ignored.
330	     *
331	     * @param owner the candidate owner to check
332	     * @return {@code true} if an owner with the same telephone number already exists
333	     */
334	    private boolean isDuplicateOwner(Owner owner) {
335	        String telephone = normalizeTelephone(owner.getTelephone());
336	        return this.clinicService.findAllOwners().stream()
337	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
338	    }
339	
340	    /**
341	     * Determines whether an owner already exists that uses the same email address as the
342	     * given candidate. Owners without an email address are never considered duplicates.
343	     * The comparison ignores letter case and surrounding or repeated whitespace.
344	     *
345	     * @param owner the candidate owner to check
346	     * @return {@code true} if an owner with the same email address already exists
347	     */
348	    private boolean isDuplicateEmail(Owner owner) {
349	        String email = normalize(owner.getEmail());
350	        if (email == null || email.isEmpty()) {
351	            return false;
352	        }
353	        return this.clinicService.findAllOwners().stream()
354	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
355	    }
356	
357	    /**
358	     * Normalizes a value for duplicate detection so that comparisons ignore letter case and
359	     * surrounding or repeated whitespace. Leading and trailing whitespace is stripped, any run
360	     * of internal whitespace collapses to a single space, and the result is lower-cased. For
361	     * example {@code "  John   Smith "} and {@code "John Smith"} both normalize to
362	     * {@code "john smith"}.
363	     *
364	     * @param value the value to normalize, may be {@code null}
365	     * @return the normalized value, or {@code null} if {@code value} is {@code null}
366	     */
367	    private static String normalize(String value) {
368	        if (value == null) {
369	            return null;
370	        }
371	        return value.strip().replaceAll("\\s+", " ").toLowerCase();
372	    }
373	
374	    /**
375	     * Normalizes a telephone number to digits only by stripping every non-digit character
376	     * (such as spaces, dashes and parentheses). This is used both to store telephone numbers
377	     * in a canonical form and to compare them for uniqueness, so that {@code "(613) 555-0100"}
378	     * and {@code "6135550100"} are treated as the same number.
379	     *
380	     * @param value the telephone number to normalize, may be {@code null}
381	     * @return the digits-only telephone number, or {@code null} if {@code value} is {@code null}
382	     */
383	    private static String normalizeTelephone(String value) {
384	        if (value == null) {
385	            return null;
386	        }
387	        return value.replaceAll("\\D", "");
388	    }
389	}
